INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(45,1,45,'A','我也是雞蛋。這裡的雞蛋比家裡的好吃。','I also have egg. The egg here is better than at home.','Moi aussi, un œuf. L''œuf ici est meilleur qu''à la maison.','わたしも たまご。 ここの たまごは 家の ものより おいしい。','나도 달걀. 여기 달걀은 집의 것보다 맛있어.','{"zh":[["我","wǒ"],["也","yě"],["是","shì"],["雞","jī"],["蛋","dàn"],["。",""],["這","zhè"],["裡","lǐ"],["的","de"],["雞","jī"],["蛋","dàn"],["比","bǐ"],["家","jiā"],["裡","lǐ"],["的","de"],["好","hǎo"],["吃","chī"],["。",""]],"ja":[["わたしも","watashimo"],["たまご","tamago"],["。",""],["ここの","kokono"],["たまごは","tamagowa"],["家の","ieno"],["ものより","monoyori"],["おいしい","oishii"],["。",""]],"ko":[["나도","nado"],["달걀","dalgyal"],[".",""],["여기","yeogi"],["달걀은","dalgyaleun"],["집의","jipui"],["것보다","geotboda"],["맛있어","matiteo"],[".",""]]}');
