INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(138,3,8,'B','數學和物理的書。書裡有很多畫和詞。','A book of math and physics. The book has many pictures and words.','Un livre de mathématiques et de physique. Il y a beaucoup d''images et de mots.','すうがくと ぶつりくの ほん。 ほんには えと ことばが たくさん ある。','수학과 물리 책이야. 책에 그림과 말이 많아.','{"zh":[["數","shù"],["學","xué"],["和","hé"],["物","wù"],["理","lǐ"],["的","de"],["書","shū"],["。",""],["書","shū"],["裡","lǐ"],["有","yǒu"],["很","hěn"],["多","duō"],["畫","huà"],["和","hé"],["詞","cí"],["。",""]],"ja":[["すうがくと","suugakuto"],["ぶつりくの","butsurikuno"],["ほん","hon"],["。",""],["ほんには","honniwa"],["えと","eto"],["ことばが","kotobaga"],["たくさん","takusan"],["ある","aru"],["。",""]],"ko":[["수학과","suhakgwa"],["물리","mulri"],["책이야","chaekiya"],[".",""],["책에","chaeke"],["그림과","geurimgwa"],["말이","mali"],["많아","mana"],[".",""]]}');
