INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(140,3,10,'B','有點難。有幾次我不懂，就去問人。','It is a little hard. Some times I do not know, so I ask people.','Un peu difficile. Quelques fois je ne sais pas, alors je demande aux gens.','すこし むずかしい。 ときどき わからないから、 人に きく。','조금 어려워. 가끔 몰라서 사람에게 물어.','{"zh":[["有","yǒu"],["點","diǎn"],["難","nán"],["。",""],["有","yǒu"],["幾","jǐ"],["次","cì"],["我","wǒ"],["不","bù"],["懂","dǒng"],["，",""],["就","jiù"],["去","qù"],["問","wèn"],["人","rén"],["。",""]],"ja":[["すこし","sukoshi"],["むずかしい","muzukashii"],["。",""],["ときどき","tokidoki"],["わからないから","wakaranaikara"],["、",""],["人に","hitoni"],["きく","kiku"],["。",""]],"ko":[["조금","jogeum"],["어려워","eoryeowo"],[".",""],["가끔","gakkeum"],["몰라서","molraseo"],["사람에게","saramege"],["물어","muleo"],[".",""]]}');
