INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(143,3,13,'A','他懂數學，也懂 chemistry。他現在在大學裡學。','He knows math and chemistry too. He studies at the university now.','Il sait les mathématiques et la chimie aussi. Il étudie à l''université maintenant.','かれは すうがくと chemistryも わかる。 いま だいがくで べんきょう している。','그는 수학과 chemistry를 알아. 지금 대학교에서 공부해.','{"zh":[["他","tā"],["懂","dǒng"],["數","shù"],["學","xué"],["，",""],["也","yě"],["懂","dǒng"],[" ",""],["c",""],["h",""],["e",""],["m",""],["i",""],["s",""],["t",""],["r",""],["y",""],["。",""],["他","tā"],["現","xiàn"],["在","zài"],["在","zài"],["大","dà"],["學","xué"],["裡","lǐ"],["學","xué"],["。",""]],"ja":[["かれは","karewa"],["すうがくと","suugakuto"],["chemistryも","chemistrymo"],["わかる","wakaru"],["。",""],["いま","ima"],["だいがくで","daigakude"],["べんきょう","benkyou"],["している","shiteiru"],["。",""]],"ko":[["그는","geuneun"],["수학과","suhakgwa"],["chemistry를","chemistryreul"],["알아","ala"],[".",""],["지금","jigeum"],["대학교에서","daehakgyoeseo"],["공부해","gongbuhae"],[".",""]]}');
