INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(144,3,14,'B','那很好。你以後也要去大學嗎？','That is good. Will you go to the university too?','C''est bien. Vas-tu aussi aller à l''université ?','それは いい。 あなたは あとで だいがくへ いく？','좋아. 너도 나중에 대학교에 갈 거야?','{"zh":[["那","nà"],["很","hěn"],["好","hǎo"],["。",""],["你","nǐ"],["以","yǐ"],["後","hòu"],["也","yě"],["要","yào"],["去","qù"],["大","dà"],["學","xué"],["嗎","ma"],["？",""]],"ja":[["それは","sorewa"],["いい","ii"],["。",""],["あなたは","anatawa"],["あとで","atode"],["だいがくへ","daigakue"],["いく","iku"],["？",""]],"ko":[["좋아","jota"],[".",""],["너도","neodo"],["나중에","najunge"],["대학교에","daehakgyoe"],["갈","gal"],["거야","geoya"],["?",""]]}');
