INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(147,3,17,'A','是很難。不過我 12 歲，還有 3 年。','It is hard. But I am 12, I have 3 more years.','C''est difficile. Mais j''ai 12 ans, j''ai encore 3 ans.','むずかしい。 けれど わたしは 12さいで、 あと 3ねん ある。','어려워. 하지만 나는 12살이고, 3년 남았어.','{"zh":[["是","shì"],["很","hěn"],["難","nán"],["。",""],["不","bù"],["過","guò"],["我","wǒ"],[" ",""],["1",""],["2",""],[" ",""],["歲","suì"],["，",""],["還","hái"],["有","yǒu"],[" ",""],["3",""],[" ",""],["年","nián"],["。",""]],"ja":[["むずかしい","muzukashii"],["。",""],["けれど","keredo"],["わたしは","watashiwa"],["12さいで","12saide"],["、",""],["あと","ato"],["3ねん","3nen"],["ある","aru"],["。",""]],"ko":[["어려워","eoryeowo"],[".",""],["하지만","hajiman"],["나는","naneun"],["12살이고","12saligo"],[",",""],["3년","3nyeon"],["남았어","namateo"],[".",""]]}');
