INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(148,3,18,'B','你先做一個小的，一個可以動的東西。','First make a small one, a thing that can move.','Fais d''abord un petit, une chose qui peut bouger.','まず ちいさい ものを 1 つ、 うごける ものを つくりな。','먼저 작은 걸 하나, 움직일 수 있는 걸 만들어.','{"zh":[["你","nǐ"],["先","xiān"],["做","zuò"],["一","yī"],["個","gè"],["小","xiǎo"],["的","de"],["，",""],["一","yī"],["個","gè"],["可","kě"],["以","yǐ"],["動","dòng"],["的","de"],["東","dōng"],["西","xī"],["。",""]],"ja":[["まず","mazu"],["ちいさい","chiisai"],["ものを","monoo"],["1","1"],["つ","tsu"],["、",""],["うごける","ugokeru"],["ものを","monoo"],["つくりな","tsukurina"],["。",""]],"ko":[["먼저","meonjeo"],["작은","jakeun"],["걸","geol"],["하나","hana"],[",",""],["움직일","umjikil"],["수","su"],["있는","itneun"],["걸","geol"],["만들어","mandeuleo"],[".",""]]}');
