INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(151,3,21,'A','媽媽今天在店裡工作。媽媽在店裡賣衣服和菜。','Mother works in the shop today. Mother sells clothes and food in the shop.','Maman travaille à la boutique aujourd''hui. Elle vend des vêtements et de la nourriture à la boutique.','おかあさんは きょう みせで はたらいて いる。 おかあさんは みせで 服と やさいを うる。','엄마는 오늘 가게에서 일해. 엄마는 가게에서 옷하고 밥을 팔아.','{"zh":[["媽","mā"],["媽","mā"],["今","jīn"],["天","tiān"],["在","zài"],["店","diàn"],["裡","lǐ"],["工","gōng"],["作","zuò"],["。",""],["媽","mā"],["媽","mā"],["在","zài"],["店","diàn"],["裡","lǐ"],["賣","mài"],["衣","yī"],["服","fú"],["和","hé"],["菜","cài"],["。",""]],"ja":[["おかあさんは","okaasanwa"],["きょう","kyou"],["みせで","misede"],["はたらいて","hataraite"],["いる","iru"],["。",""],["おかあさんは","okaasanwa"],["みせで","misede"],["服と","fukuto"],["やさいを","yasaio"],["うる","uru"],["。",""]],"ko":[["엄마는","eommaneun"],["오늘","oneul"],["가게에서","gageeseo"],["일해","ilhae"],[".",""],["엄마는","eommaneun"],["가게에서","gageeseo"],["옷하고","othago"],["밥을","bapeul"],["팔아","pala"],[".",""]]}');
