INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(153,3,23,'A','爸爸在 factory 做車。他很忙，每天早出晚回。','Father makes cars at factory. He is very busy, he goes out early and comes back late every day.','Père fait des voitures à la factory. Il est très occupé, il part tôt et revient tard chaque jour.','おとうさんは factoryで くるまを つくる。 かれは とても いそがしくて、 まいにち はやく いって おそく もどる。','아빠는 factory에서 차를 만들어. 아빠는 너무 바빠서 매일 일찍 나가 늦게 와.','{"zh":[["爸","bà"],["爸","bà"],["在","zài"],[" ",""],["f",""],["a",""],["c",""],["t",""],["o",""],["r",""],["y",""],[" ",""],["做","zuò"],["車","chē"],["。",""],["他","tā"],["很","hěn"],["忙","máng"],["，",""],["每","měi"],["天","tiān"],["早","zǎo"],["出","chū"],["晚","wǎn"],["回","huí"],["。",""]],"ja":[["おとうさんは","otousanwa"],["factoryで","factoryde"],["くるまを","kurumao"],["つくる","tsukuru"],["。",""],["かれは","karewa"],["とても","totemo"],["いそがしくて","isogashikute"],["、",""],["まいにち","mainichi"],["はやく","hayaku"],["いって","itte"],["おそく","osoku"],["もどる","modoru"],["。",""]],"ko":[["아빠는","appaneun"],["factory에서","factoryeseo"],["차를","chareul"],["만들어","mandeuleo"],[".",""],["아빠는","appaneun"],["너무","neomu"],["바빠서","bappaseo"],["매일","maeil"],["일찍","iljjik"],["나가","naga"],["늦게","neutge"],["와","wa"],[".",""]]}');
