INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(162,3,32,'B','下午我要去醫生那裡。我有點病，醫生給我 medicine。','This afternoon I go to the doctor. I am a little sick, the doctor gives me medicine.','Cet après-midi, je vais chez le médecin. Je suis un peu malade, le médecin me donne un médicament.','ごごに いしゃに いく。 わたしは すこし びょうきだ、 いしゃが medicineを くれる。','오후에 의사에게 갈 거야. 나는 조금 아파서 의사가 medicine을 줘.','{"zh":[["下","xià"],["午","wǔ"],["我","wǒ"],["要","yào"],["去","qù"],["醫","yī"],["生","shēng"],["那","nà"],["裡","lǐ"],["。",""],["我","wǒ"],["有","yǒu"],["點","diǎn"],["病","bìng"],["，",""],["醫","yī"],["生","shēng"],["給","gěi"],["我","wǒ"],[" ",""],["m",""],["e",""],["d",""],["i",""],["c",""],["i",""],["n",""],["e",""],["。",""]],"ja":[["ごごに","gogoni"],["いしゃに","ishani"],["いく","iku"],["。",""],["わたしは","watashiwa"],["すこし","sukoshi"],["びょうきだ","byoukida"],["、",""],["いしゃが","ishaga"],["medicineを","medicineo"],["くれる","kureru"],["。",""]],"ko":[["오후에","ohue"],["의사에게","uisaege"],["갈","gal"],["거야","geoya"],[".",""],["나는","naneun"],["조금","jogeum"],["아파서","apaseo"],["의사가","uisaga"],["medicine을","medicineeul"],["줘","jwo"],[".",""]]}');
