INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(163,3,33,'A','那你要早點去。多喝水，多睡覺。','Then you must go early. Drink much water, sleep much.','Alors tu dois y aller tôt. Bois beaucoup d''eau, dors beaucoup.','じゃ はやく いって。 水を たくさん のみ、 よく ねな。','그럼 일찍 가. 물 많이 마시고, 많이 자.','{"zh":[["那","nà"],["你","nǐ"],["要","yào"],["早","zǎo"],["點","diǎn"],["去","qù"],["。",""],["多","duō"],["喝","hē"],["水","shuǐ"],["，",""],["多","duō"],["睡","shuì"],["覺","jué"],["。",""]],"ja":[["じゃ","ja"],["はやく","hayaku"],["いって","itte"],["。",""],["水を","mizuo"],["たくさん","takusan"],["のみ","nomi"],["、",""],["よく","yoku"],["ねな","nena"],["。",""]],"ko":[["그럼","geureom"],["일찍","iljjik"],["가","ga"],[".",""],["물","mul"],["많이","mani"],["마시고","masigo"],[",",""],["많이","mani"],["자","ja"],[".",""]]}');
