INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(164,3,34,'B','謝謝你。你說得對。我去醫生那裡拿 medicine。','Thank you. You are right. I go to the doctor to get medicine.','Merci. Tu as raison. Je vais chez le médecin pour prendre un médicament.','ありがとう。 あなたは ただしい。 いしゃに medicineを とりに いく。','고마워. 네 말이 맞아. 의사에게 medicine을 받으러 갈게.','{"zh":[["謝","xiè"],["謝","xiè"],["你","nǐ"],["。",""],["你","nǐ"],["說","shuō"],["得","dé"],["對","duì"],["。",""],["我","wǒ"],["去","qù"],["醫","yī"],["生","shēng"],["那","nà"],["裡","lǐ"],["拿","ná"],[" ",""],["m",""],["e",""],["d",""],["i",""],["c",""],["i",""],["n",""],["e",""],["。",""]],"ja":[["ありがとう","arigatou"],["。",""],["あなたは","anatawa"],["ただしい","tadashii"],["。",""],["いしゃに","ishani"],["medicineを","medicineo"],["とりに","torini"],["いく","iku"],["。",""]],"ko":[["고마워","gomawo"],[".",""],["네","ne"],["말이","mali"],["맞아","mata"],[".",""],["의사에게","uisaege"],["medicine을","medicineeul"],["받으러","bateureo"],["갈게","galge"],[".",""]]}');
