INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(172,3,42,'B','我不怕。我最怕的是做不完事。','I am not afraid. What I fear most is not finishing the work.','Je n''ai pas peur. Ce que je crains le plus, c''est de ne pas finir le travail.','わたしは こわくない。 いちばん こわいのは しごとを やりきれない ことだ。','나는 안 무서워. 내가 제일 무서운 건 일을 끝내지 못하는 거야.','{"zh":[["我","wǒ"],["不","bù"],["怕","pà"],["。",""],["我","wǒ"],["最","zuì"],["怕","pà"],["的","de"],["是","shì"],["做","zuò"],["不","bù"],["完","wán"],["事","shì"],["。",""]],"ja":[["わたしは","watashiwa"],["こわくない","kowakunai"],["。",""],["いちばん","ichiban"],["こわいのは","kowainowa"],["しごとを","shigotoo"],["やりきれない","yarikirenai"],["ことだ","kotoda"],["。",""]],"ko":[["나는","naneun"],["안","an"],["무서워","museowo"],[".",""],["내가","naega"],["제일","jeil"],["무서운","museoun"],["건","geon"],["일을","ileul"],["끝내지","kkeutnaeji"],["못하는","mothaneun"],["거야","geoya"],[".",""]]}');
