INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(175,3,45,'A','晚上 9 點我睡覺。睡覺以前我看一點書。','At 9 at night I sleep. Before I sleep I read a little book.','À 9 heures le soir, je dors. Avant de dormir, je lis un peu.','よる 9じに ねる。 ねる まえに ほんを すこし よむ。','밤 9시에 자. 자기 전에 책 좀 읽어.','{"zh":[["晚","wǎn"],["上","shàng"],[" ",""],["9",""],[" ",""],["點","diǎn"],["我","wǒ"],["睡","shuì"],["覺","jué"],["。",""],["睡","shuì"],["覺","jué"],["以","yǐ"],["前","qián"],["我","wǒ"],["看","kàn"],["一","yī"],["點","diǎn"],["書","shū"],["。",""]],"ja":[["よる","yoru"],["9じに","9jini"],["ねる","neru"],["。",""],["ねる","neru"],["まえに","maeni"],["ほんを","hono"],["すこし","sukoshi"],["よむ","yomu"],["。",""]],"ko":[["밤","bam"],["9시에","9sie"],["자","ja"],[".",""],["자기","jagi"],["전에","jeone"],["책","chaek"],["좀","jom"],["읽어","ikeo"],[".",""]]}');
