INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(177,3,47,'A','是的，也有 English 書。English 的字多，我看得很慢。','Yes, and English books too. English has many words, I read very slowly.','Oui, et des livres en anglais. L''anglais a beaucoup de mots, je lis très lentement.','そう、 Englishの ほんも ある。 Englishは ことばが たくさん ある、わたしは ゆっくり よむ。','응, English 책도 있어. English는 말이 많아, 나는 천천히 읽어.','{"zh":[["是","shì"],["的","de"],["，",""],["也","yě"],["有","yǒu"],[" ",""],["E",""],["n",""],["g",""],["l",""],["i",""],["s",""],["h",""],[" ",""],["書","shū"],["。",""],["E",""],["n",""],["g",""],["l",""],["i",""],["s",""],["h",""],[" ",""],["的","de"],["字","zì"],["多","duō"],["，",""],["我","wǒ"],["看","kàn"],["得","dé"],["很","hěn"],["慢","màn"],["。",""]],"ja":[["そう","sou"],["、",""],["Englishの","Englishno"],["ほんも","hommo"],["ある","aru"],["。",""],["Englishは","Englishwa"],["ことばが","kotobaga"],["たくさん","takusan"],["ある","aru"],["、",""],["わたしは","watashiwa"],["ゆっくり","yukkuri"],["よむ","yomu"],["。",""]],"ko":[["응","eung"],[",",""],["English","English"],["책도","chaekdo"],["있어","iteo"],[".",""],["English는","Englishneun"],["말이","mali"],["많아","mana"],[",",""],["나는","naneun"],["천천히","cheoncheonhi"],["읽어","ikeo"],[".",""]]}');
