INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(179,3,49,'A','我也是。我只會說一點 English。','Me too. I can only speak a little English.','Moi aussi. Je ne parle qu''un peu anglais.','わたしも そう。 Englishは すこししか はなせない。','나도 그래. English는 조금밖에 못해.','{"zh":[["我","wǒ"],["也","yě"],["是","shì"],["。",""],["我","wǒ"],["只","zhǐ"],["會","huì"],["說","shuō"],["一","yī"],["點","diǎn"],[" ",""],["E",""],["n",""],["g",""],["l",""],["i",""],["s",""],["h",""],["。",""]],"ja":[["わたしも","watashimo"],["そう","sou"],["。",""],["Englishは","Englishwa"],["すこししか","sukoshishika"],["はなせない","hanasenai"],["。",""]],"ko":[["나도","nado"],["그래","geurae"],[".",""],["English는","Englishneun"],["조금밖에","jogeumbake"],["못해","mothae"],[".",""]]}');
