INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(180,3,50,'B','沒事。每天用一點，慢慢就會了。','No problem. Use it a little every day, slowly you will do it.','Ce n''est rien. Un peu chaque jour, et petit à petit tu sauras.','だいじょうぶ。 まいにち すこし つかえば、 ゆっくり できる ようになる。','괜찮아. 매일 조금만 쓰면 천천히 할 수 있어.','{"zh":[["沒","méi"],["事","shì"],["。",""],["每","měi"],["天","tiān"],["用","yòng"],["一","yī"],["點","diǎn"],["，",""],["慢","màn"],["慢","màn"],["就","jiù"],["會","huì"],["了","le"],["。",""]],"ja":[["だいじょうぶ","daijoubu"],["。",""],["まいにち","mainichi"],["すこし","sukoshi"],["つかえば","tsukaeba"],["、",""],["ゆっくり","yukkuri"],["できる","dekiru"],["ようになる","youninaru"],["。",""]],"ko":[["괜찮아","gwaenchana"],[".",""],["매일","maeil"],["조금만","jogeumman"],["쓰면","sseumyeon"],["천천히","cheoncheonhi"],["할","hal"],["수","su"],["있어","iteo"],[".",""]]}');
