INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(181,3,51,'A','你要買什麼？我下午去 market 買東西。','What do you want to buy? I go to market in the afternoon to buy things.','Que veux-tu acheter ? Cet après-midi, je vais au marché pour acheter des choses.','なにを かうの？ わたしは ごごに marketへ かいに いく。','뭐 살 거야? 나는 오후에 market에 가서 사.','{"zh":[["你","nǐ"],["要","yào"],["買","mǎi"],["什","shén"],["麼","me"],["？",""],["我","wǒ"],["下","xià"],["午","wǔ"],["去","qù"],[" ",""],["m",""],["a",""],["r",""],["k",""],["e",""],["t",""],[" ",""],["買","mǎi"],["東","dōng"],["西","xī"],["。",""]],"ja":[["なにを","nanio"],["かうの","kauno"],["？",""],["わたしは","watashiwa"],["ごごに","gogoni"],["marketへ","markete"],["かいに","kaini"],["いく","iku"],["。",""]],"ko":[["뭐","mwo"],["살","sal"],["거야","geoya"],["?",""],["나는","naneun"],["오후에","ohue"],["market에","markete"],["가서","gaseo"],["사","sa"],[".",""]]}');
