INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(182,3,52,'B','我要買水果和肉。還要給女兒買 1 個書和 1 個 toy。','I want to buy fruit and meat. I also want to buy 1 book and 1 toy for my girl.','Je veux acheter des fruits et de la viande. Je veux aussi acheter 1 livre et 1 jouet pour ma fille.','わたしは 果物と にくを かう。 むすめのために ほん 1つと toy 1つを かいたい。','나는 과일하고 고기를 사. 딸에게 책 1개랑 toy 1개도 사려고.','{"zh":[["我","wǒ"],["要","yào"],["買","mǎi"],["水","shuǐ"],["果","guǒ"],["和","hé"],["肉","ròu"],["。",""],["還","hái"],["要","yào"],["給","gěi"],["女","nǚ"],["兒","ér"],["買","mǎi"],[" ",""],["1",""],[" ",""],["個","gè"],["書","shū"],["和","hé"],[" ",""],["1",""],[" ",""],["個","gè"],[" ",""],["t",""],["o",""],["y",""],["。",""]],"ja":[["わたしは","watashiwa"],["果物と","kudamonoto"],["にくを","nikuo"],["かう","kau"],["。",""],["むすめのために","musumenotameni"],["ほん","hon"],["1つと","1tsuto"],["toy","toy"],["1つを","1tsuo"],["かいたい","kaitai"],["。",""]],"ko":[["나는","naneun"],["과일하고","gwailhago"],["고기를","gogireul"],["사","sa"],[".",""],["딸에게","ttalege"],["책","chaek"],["1개랑","1gaerang"],["toy","toy"],["1개도","1gaedo"],["사려고","saryeogo"],[".",""]]}');
