INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(195,3,65,'B','我有 2 千塊錢。我要給 rent 的錢，所以不多了。','I have 2 thousand. I have to give rent money, so it is not much.','J''ai 2 mille. Je dois payer le rent, donc il n''y en a pas beaucoup.','わたしは 2せんえん ある。 rentの おかねが いえるから、 あまりない。','나는 2천 원 있어. rent를 줘야 하니까, 많지 않아.','{"zh":[["我","wǒ"],["有","yǒu"],[" ",""],["2",""],[" ",""],["千","qiān"],["塊","kuài"],["錢","qián"],["。",""],["我","wǒ"],["要","yào"],["給","gěi"],[" ",""],["r",""],["e",""],["n",""],["t",""],[" ",""],["的","de"],["錢","qián"],["，",""],["所","suǒ"],["以","yǐ"],["不","bù"],["多","duō"],["了","le"],["。",""]],"ja":[["わたしは","watashiwa"],["2せんえん","2senen"],["ある","aru"],["。",""],["rentの","rentno"],["おかねが","okanega"],["いえるから","ierukara"],["、",""],["あまりない","amarinai"],["。",""]],"ko":[["나는","naneun"],["2천","2cheon"],["원","won"],["있어","iteo"],[".",""],["rent를","rentreul"],["줘야","jwoya"],["하니까","hanikka"],[",",""],["많지","manji"],["않아","ana"],[".",""]]}');
