INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(201,3,71,'B','不買。我的衣服還能穿。我的錢不花，以後去看海。','No. My clothes can still be worn. I do not spend my money, later I will see the sea.','Non. Mes vêtements peuvent encore être portés. Je ne dépense pas mon argent, plus tard je verrai la mer.','買わない。 わたしの 服は まだ きれる。 おかねは つかわない、 あとで 海を みに いく。','안 사. 내 옷은 아직 입을 수 있어. 돈은 안 쓸 거야, 나중에 바다를 볼 거야.','{"zh":[["不","bù"],["買","mǎi"],["。",""],["我","wǒ"],["的","de"],["衣","yī"],["服","fú"],["還","hái"],["能","néng"],["穿","chuān"],["。",""],["我","wǒ"],["的","de"],["錢","qián"],["不","bù"],["花","huā"],["，",""],["以","yǐ"],["後","hòu"],["去","qù"],["看","kàn"],["海","hǎi"],["。",""]],"ja":[["買わない","kawanai"],["。",""],["わたしの","watashino"],["服は","fukuwa"],["まだ","mada"],["きれる","kireru"],["。",""],["おかねは","okanewa"],["つかわない","tsukawanai"],["、",""],["あとで","atode"],["海を","umio"],["みに","mini"],["いく","iku"],["。",""]],"ko":[["안","an"],["사","sa"],[".",""],["내","nae"],["옷은","oteun"],["아직","ajik"],["입을","ipeul"],["수","su"],["있어","iteo"],[".",""],["돈은","doneun"],["안","an"],["쓸","sseul"],["거야","geoya"],[",",""],["나중에","najunge"],["바다를","badareul"],["볼","bol"],["거야","geoya"],[".",""]]}');
