INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(202,3,72,'A','海！我最想去的地方也是海。','The sea! The place I want to go most is also the sea.','La mer ! L''endroit où je veux aller le plus est aussi la mer.','海！ わたしが いちばん いきたい ものも 海だ。','바다! 내가 제일 가고 싶은 곳도 바다야.','{"zh":[["海","hǎi"],["！",""],["我","wǒ"],["最","zuì"],["想","xiǎng"],["去","qù"],["的","de"],["地","dì"],["方","fāng"],["也","yě"],["是","shì"],["海","hǎi"],["。",""]],"ja":[["海","umi"],["！",""],["わたしが","watashiga"],["いちばん","ichiban"],["いきたい","ikitai"],["ものも","monomo"],["海だ","umida"],["。",""]],"ko":[["바다","bada"],["!",""],["내가","naega"],["제일","jeil"],["가고","gago"],["싶은","sipeun"],["곳도","gotdo"],["바다야","badaya"],[".",""]]}');
