INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(203,3,73,'B','我 3 個月的時候去過一次。海很大，天和水是一個色。','I went there 3 months ago. The sea is very big, the sky and the water are one color.','J''y suis allé il y a 3 mois. La mer est très grande, le ciel et l''eau sont de la même couleur.','3げつまえに 1かい いった。 海は とても 大きくて、 そらと みずは おなじ いろだ。','3개월 전에 한 번 갔어. 바다가 아주 커서, 하늘과 물은 같은 색이야.','{"zh":[["我","wǒ"],[" ",""],["3",""],[" ",""],["個","gè"],["月","yuè"],["的","de"],["時","shí"],["候","hòu"],["去","qù"],["過","guò"],["一","yī"],["次","cì"],["。",""],["海","hǎi"],["很","hěn"],["大","dà"],["，",""],["天","tiān"],["和","hé"],["水","shuǐ"],["是","shì"],["一","yī"],["個","gè"],["色","sè"],["。",""]],"ja":[["3げつまえに","3getsumaeni"],["1かい","1kai"],["いった","itta"],["。",""],["海は","umiwa"],["とても","totemo"],["大きくて","ookikute"],["、",""],["そらと","sorato"],["みずは","mizuwa"],["おなじ","onaji"],["いろだ","iroda"],["。",""]],"ko":[["3개월","3gaewol"],["전에","jeone"],["한","han"],["번","beon"],["갔어","gateo"],[".",""],["바다가","badaga"],["아주","aju"],["커서","keoseo"],[",",""],["하늘과","haneulgwa"],["물은","muleun"],["같은","gateun"],["색이야","saekiya"],[".",""]]}');
