INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(208,3,78,'B','我有 umbrella，你沒有嗎？','I have an umbrella, do not you?','J''ai un parapluie, et toi ?','わたしは umbrellaを もって いる、 あなたは？','나는 umbrella가 있어, 너는?','{"zh":[["我","wǒ"],["有","yǒu"],[" ",""],["u",""],["m",""],["b",""],["r",""],["e",""],["l",""],["l",""],["a",""],["，",""],["你","nǐ"],["沒","méi"],["有","yǒu"],["嗎","ma"],["？",""]],"ja":[["わたしは","watashiwa"],["umbrellaを","umbrellao"],["もって","motte"],["いる","iru"],["、",""],["あなたは","anatawa"],["？",""]],"ko":[["나는","naneun"],["umbrella가","umbrellaga"],["있어","iteo"],[",",""],["너는","neoneun"],["?",""]]}');
