INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(209,3,79,'A','沒有。沒事。我走快一點回去。','No. It is all right. I will go home faster.','Non. Ce n''est rien. Je vais aller à la maison plus vite.','ない。 だいじょうぶ。 わたしは はやく かえって いく。','없어. 괜찮아. 더 빨리 갈게.','{"zh":[["沒","méi"],["有","yǒu"],["。",""],["沒","méi"],["事","shì"],["。",""],["我","wǒ"],["走","zǒu"],["快","kuài"],["一","yī"],["點","diǎn"],["回","huí"],["去","qù"],["。",""]],"ja":[["ない","nai"],["。",""],["だいじょうぶ","daijoubu"],["。",""],["わたしは","watashiwa"],["はやく","hayaku"],["かえって","kaette"],["いく","iku"],["。",""]],"ko":[["없어","eopeo"],[".",""],["괜찮아","gwaenchana"],[".",""],["더","deo"],["빨리","ppalri"],["갈게","galge"],[".",""]]}');
