INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(210,3,80,'B','我在這裡等你。不要走太快。','I wait for you here. Do not walk too fast.','Je t''attends ici. Ne marche pas trop vite.','ここで まってる。 あんまり はやく あるかないで。','여기서 기다릴게. 너무 빨리 걷지 마.','{"zh":[["我","wǒ"],["在","zài"],["這","zhè"],["裡","lǐ"],["等","děng"],["你","nǐ"],["。",""],["不","bù"],["要","yào"],["走","zǒu"],["太","tài"],["快","kuài"],["。",""]],"ja":[["ここで","kokode"],["まってる","matteru"],["。",""],["あんまり","ammari"],["はやく","hayaku"],["あるかないで","arukanaide"],["。",""]],"ko":[["여기서","yeogiseo"],["기다릴게","gidarilge"],[".",""],["너무","neomu"],["빨리","ppalri"],["걷지","geotji"],["마","ma"],[".",""]]}');
