INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(211,3,81,'A','5 分鐘後我回來。','I will come back after 5 minutes.','Je reviens dans 5 minutes.','5ぷんごに くる。','5분 후에 돌아올게.','{"zh":[["5",""],[" ",""],["分","fēn"],["鐘","zhōng"],["後","hòu"],["我","wǒ"],["回","huí"],["來","lái"],["。",""]],"ja":[["5ぷんごに","5pungoni"],["くる","kuru"],["。",""]],"ko":[["5분","5bun"],["후에","hue"],["돌아올게","dolaolge"],[".",""]]}');
