INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(212,3,82,'B','你回來了。身上都是水。','You are back. Your body is all water.','Tu es de retour. Ton corps est tout de l''eau.','かえったんだね。 からだに みずが なって いる。','돌아왔구나. 온몸에 물이야.','{"zh":[["你","nǐ"],["回","huí"],["來","lái"],["了","le"],["。",""],["身","shēn"],["上","shàng"],["都","dōu"],["是","shì"],["水","shuǐ"],["。",""]],"ja":[["かえったんだね","kaettandane"],["。",""],["からだに","karadani"],["みずが","mizuga"],["なって","natte"],["いる","iru"],["。",""]],"ko":[["돌아왔구나","dolawatguna"],[".",""],["온몸에","onmome"],["물이야","muliya"],[".",""]]}');
