INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(213,3,83,'A','是。我走得快，不怕。','Yes. I walk fast, I am not afraid.','Oui. Je marche vite, je n''ai pas peur.','そう。 わたしは はやく あるく、 こわくない。','응. 빨리 걷니까, 안 무서워.','{"zh":[["是","shì"],["。",""],["我","wǒ"],["走","zǒu"],["得","dé"],["快","kuài"],["，",""],["不","bù"],["怕","pà"],["。",""]],"ja":[["そう","sou"],["。",""],["わたしは","watashiwa"],["はやく","hayaku"],["あるく","aruku"],["、",""],["こわくない","kowakunai"],["。",""]],"ko":[["응","eung"],[".",""],["빨리","ppalri"],["걷니까","geotnikka"],[",",""],["안","an"],["무서워","museowo"],[".",""]]}');
