INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(214,3,84,'B','快去洗一下，用熱水，再穿衣服。','Go and wash a little, use hot water, then wear your clothes.','Va te laver un peu, utilise de l''eau chaude, puis mets tes vêtements.','はやく あらって、 あたたかい みずを つかって、 服を きて。','빨리 씻어, 뜨거운 물을 써, 옷을 입어.','{"zh":[["快","kuài"],["去","qù"],["洗","xǐ"],["一","yī"],["下","xià"],["，",""],["用","yòng"],["熱","rè"],["水","shuǐ"],["，",""],["再","zài"],["穿","chuān"],["衣","yī"],["服","fú"],["。",""]],"ja":[["はやく","hayaku"],["あらって","aratte"],["、",""],["あたたかい","atatakai"],["みずを","mizuo"],["つかって","tsukatte"],["、",""],["服を","fukuo"],["きて","kite"],["。",""]],"ko":[["빨리","ppalri"],["씻어","ssiteo"],[",",""],["뜨거운","tteugeoun"],["물을","muleul"],["써","sseo"],[",",""],["옷을","oteul"],["입어","ipeo"],[".",""]]}');
