INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(215,3,85,'A','好。媽媽做好飯了，在家等我。','Ok. Mother has cooked the food, she waits for me at home.','Ok. Maman a cuisine, elle m''attend à la maison.','いい。 おかあさんが ごはんを つくり ました、 うちで まって いる。','그래. 엄마가 밥을 했어, 집에서 기다려.','{"zh":[["好","hǎo"],["。",""],["媽","mā"],["媽","mā"],["做","zuò"],["好","hǎo"],["飯","fàn"],["了","le"],["，",""],["在","zài"],["家","jiā"],["等","děng"],["我","wǒ"],["。",""]],"ja":[["いい","ii"],["。",""],["おかあさんが","okaasanga"],["ごはんを","gohano"],["つくり","tsukuri"],["ました","mashita"],["、",""],["うちで","uchide"],["まって","matte"],["いる","iru"],["。",""]],"ko":[["그래","geurae"],[".",""],["엄마가","eommaga"],["밥을","bapeul"],["했어","haeteo"],[",",""],["집에서","jipeseo"],["기다려","gidaryeo"],[".",""]]}');
