INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(216,3,86,'B','我也回家。明天見。','I go home too. See you tomorrow.','Je rentre aussi. À demain.','わたしも かえって いく。 あしたね。','나도 집에 가. 내일 봐.','{"zh":[["我","wǒ"],["也","yě"],["回","huí"],["家","jiā"],["。",""],["明","míng"],["天","tiān"],["見","jiàn"],["。",""]],"ja":[["わたしも","watashimo"],["かえって","kaette"],["いく","iku"],["。",""],["あしたね","ashitane"],["。",""]],"ko":[["나도","nado"],["집에","jipe"],["가","ga"],[".",""],["내일","naeil"],["봐","bwa"],[".",""]]}');
