INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(217,3,87,'A','明天見，玩得開心。','See you tomorrow, play and be happy.','À demain. Joues bien.','あしたね、 よく あそんで うれしい もちで。','내일 봐, 잘 놀아.','{"zh":[["明","míng"],["天","tiān"],["見","jiàn"],["，",""],["玩","wán"],["得","dé"],["開","kāi"],["心","xīn"],["。",""]],"ja":[["あしたね","ashitane"],["、",""],["よく","yoku"],["あそんで","asonde"],["うれしい","ureshii"],["もちで","mochide"],["。",""]],"ko":[["내일","naeil"],["봐","bwa"],[",",""],["잘","jal"],["놀아","nola"],[".",""]]}');
