INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(218,3,88,'A','對了，我還想問你。','By the way, I want to ask you too.','Au fait, je veux aussi te demander.','そういえば、 わたしも ききたいことが ある。','그러고 보니, 나도 묻고 싶은 게 있어.','{"zh":[["對","duì"],["了","le"],["，",""],["我","wǒ"],["還","hái"],["想","xiǎng"],["問","wèn"],["你","nǐ"],["。",""]],"ja":[["そういえば","souieba"],["、",""],["わたしも","watashimo"],["ききたいことが","kikitaikotoga"],["ある","aru"],["。",""]],"ko":[["그러고","geureogo"],["보니","boni"],[",",""],["나도","nado"],["묻고","mutgo"],["싶은","sipeun"],["게","ge"],["있어","iteo"],[".",""]]}');
