INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(220,3,90,'A','你上一次去海是什麼時候？','When did you go to the sea before?','Quand es-tu allé à la mer avant ?','さいごに 海へ いったのは いつ？','마지막으로 바다에 간 건 언제야?','{"zh":[["你","nǐ"],["上","shàng"],["一","yī"],["次","cì"],["去","qù"],["海","hǎi"],["是","shì"],["什","shén"],["麼","me"],["時","shí"],["候","hòu"],["？",""]],"ja":[["さいごに","saigoni"],["海へ","umie"],["いったのは","ittanowa"],["いつ","itsu"],["？",""]],"ko":[["마지막으로","majimakeuro"],["바다에","badae"],["간","gan"],["건","geon"],["언제야","eonjeya"],["?",""]]}');
