INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(223,3,93,'B','不是。我住在北方的一個城裡。從這裡到海要 2 天的路。','No. I live in a city far away. From here to the sea is 2 days of road.','Non. J''habite dans une ville très loin. D''ici à la mer, il y a 2 jours de route.','いいえ。 わたしは 遠い ある まちに すんで いる。 ここから 海まで 2にち の みちだ。','아니. 나는 멀리 있는 도시에 살아. 여기서 바다까지 2일 길이야.','{"zh":[["不","bù"],["是","shì"],["。",""],["我","wǒ"],["住","zhù"],["在","zài"],["北","běi"],["方","fāng"],["的","de"],["一","yī"],["個","gè"],["城","chéng"],["裡","lǐ"],["。",""],["從","cóng"],["這","zhè"],["裡","lǐ"],["到","dào"],["海","hǎi"],["要","yào"],[" ",""],["2",""],[" ",""],["天","tiān"],["的","de"],["路","lù"],["。",""]],"ja":[["いいえ","iie"],["。",""],["わたしは","watashiwa"],["遠い","tooi"],["ある","aru"],["まちに","machini"],["すんで","sunde"],["いる","iru"],["。",""],["ここから","kokokara"],["海まで","umimade"],["2にち","2nichi"],["の","no"],["みちだ","michida"],["。",""]],"ko":[["아니","ani"],[".",""],["나는","naneun"],["멀리","meolri"],["있는","itneun"],["도시에","dosie"],["살아","sala"],[".",""],["여기서","yeogiseo"],["바다까지","badakkaji"],["2일","2il"],["길이야","giliya"],[".",""]]}');
