INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(224,3,94,'A','那很遠。你要坐車嗎？','That is far. Do you go by car?','C''est loin. Tu vas en voiture ?','それは 遠い。 くるまで いくの？','그건 멀어. 차로 가?','{"zh":[["那","nà"],["很","hěn"],["遠","yuǎn"],["。",""],["你","nǐ"],["要","yào"],["坐","zuò"],["車","chē"],["嗎","ma"],["？",""]],"ja":[["それは","sorewa"],["遠い","tooi"],["。",""],["くるまで","kurumade"],["いくの","ikuno"],["？",""]],"ko":[["그건","geugeon"],["멀어","meoleo"],[".",""],["차로","charo"],["가","ga"],["?",""]]}');
