INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(225,3,95,'B','要坐車，再坐 boat。車的錢不貴，不過要早點起。','By car, then by boat. The car money is not expensive, but I must stand up early.','En voiture, puis en bateau. L''argent de la voiture n''est pas cher, mais je dois me lever tôt.','くるまに のって、それから boatに のる。 くるまの おかねは やすく ないけど、 はやく おきなければ。','차를 타고, 그다음 boat를 타. 차 값은 비싸지 않지만, 일찍 일어나야 해.','{"zh":[["要","yào"],["坐","zuò"],["車","chē"],["，",""],["再","zài"],["坐","zuò"],[" ",""],["b",""],["o",""],["a",""],["t",""],["。",""],["車","chē"],["的","de"],["錢","qián"],["不","bù"],["貴","guì"],["，",""],["不","bù"],["過","guò"],["要","yào"],["早","zǎo"],["點","diǎn"],["起","qǐ"],["。",""]],"ja":[["くるまに","kurumani"],["のって","notte"],["、",""],["それから","sorekara"],["boatに","boatni"],["のる","noru"],["。",""],["くるまの","kurumano"],["おかねは","okanewa"],["やすく","yasuku"],["ないけど","naikedo"],["、",""],["はやく","hayaku"],["おきなければ","okinakereba"],["。",""]],"ko":[["차를","chareul"],["타고","tago"],[",",""],["그다음","geudaeum"],["boat를","boatreul"],["타","ta"],[".",""],["차","cha"],["값은","gapeun"],["비싸지","bissaji"],["않지만","anjiman"],[",",""],["일찍","iljjik"],["일어나야","ileonaya"],["해","hae"],[".",""]]}');
