INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(227,3,97,'B','不。這次和家人一起去。我哥哥和姐姐都去。','No. This time I go with my family. My big brother and my big sister both go too.','Non. Cette fois je vais avec ma famille. Mon grand frère et ma grande sœur y vont aussi.','いいえ。 こんどは かぞくと いっしょに いく。 おにいさんと おねえさんも いく。','아니. 이번에는 가족이랑 같이 가. 형이랑 누나도 가.','{"zh":[["不","bù"],["。",""],["這","zhè"],["次","cì"],["和","hé"],["家","jiā"],["人","rén"],["一","yī"],["起","qǐ"],["去","qù"],["。",""],["我","wǒ"],["哥","gē"],["哥","gē"],["和","hé"],["姐","jiě"],["姐","jiě"],["都","dōu"],["去","qù"],["。",""]],"ja":[["いいえ","iie"],["。",""],["こんどは","kondowa"],["かぞくと","kazokuto"],["いっしょに","isshoni"],["いく","iku"],["。",""],["おにいさんと","oniisanto"],["おねえさんも","oneesammo"],["いく","iku"],["。",""]],"ko":[["아니","ani"],[".",""],["이번에는","ibeoneneun"],["가족이랑","gajokirang"],["같이","gati"],["가","ga"],[".",""],["형이랑","hyeongirang"],["누나도","nunado"],["가","ga"],[".",""]]}');
