INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(229,3,99,'B','是。爸爸也想去，他會做很多菜。','Yes. Father wants to go too, he can make much food.','Oui. Père veut venir aussi, il sait faire beaucoup de nourriture.','そう。 おとうさんも いきたい、 かれは たくさんの ものが できる。','응. 아빠도 가고 싶어 하셔, 많은 요리를 할 수 있어.','{"zh":[["是","shì"],["。",""],["爸","bà"],["爸","bà"],["也","yě"],["想","xiǎng"],["去","qù"],["，",""],["他","tā"],["會","huì"],["做","zuò"],["很","hěn"],["多","duō"],["菜","cài"],["。",""]],"ja":[["そう","sou"],["。",""],["おとうさんも","otousammo"],["いきたい","ikitai"],["、",""],["かれは","karewa"],["たくさんの","takusanno"],["ものが","monoga"],["できる","dekiru"],["。",""]],"ko":[["응","eung"],[".",""],["아빠도","appado"],["가고","gago"],["싶어","sipeo"],["하셔","hasyeo"],[",",""],["많은","maneun"],["요리를","yorireul"],["할","hal"],["수","su"],["있어","iteo"],[".",""]]}');
