INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(230,3,100,'A','你爸爸做菜很好吃嗎？','Does your father cook well?','Ton père cuisine-t-il bien ?','おとうさんの りょうりは おいしい？','아빠 요리는 잘해?','{"zh":[["你","nǐ"],["爸","bà"],["爸","bà"],["做","zuò"],["菜","cài"],["很","hěn"],["好","hǎo"],["吃","chī"],["嗎","ma"],["？",""]],"ja":[["おとうさんの","otousanno"],["りょうりは","ryouriwa"],["おいしい","oishii"],["？",""]],"ko":[["아빠","appa"],["요리는","yorineun"],["잘해","jalhae"],["?",""]]}');
