INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(231,3,101,'B','他做的魚菜最好吃。他做菜比我媽媽好。','His fish dish is the best. He cooks better than my mother.','Son poisson est très bon. Il cuisine mieux que ma mère.','かれの さかなの りょうりが いちばん おいしい。 りょうりは おかあさんより じょうずだ。','아빠가 만든 물고기 요리가 제일 맛있어. 아빠는 엄마보다 요리를 잘해.','{"zh":[["他","tā"],["做","zuò"],["的","de"],["魚","yú"],["菜","cài"],["最","zuì"],["好","hǎo"],["吃","chī"],["。",""],["他","tā"],["做","zuò"],["菜","cài"],["比","bǐ"],["我","wǒ"],["媽","mā"],["媽","mā"],["好","hǎo"],["。",""]],"ja":[["かれの","kareno"],["さかなの","sakanano"],["りょうりが","ryouriga"],["いちばん","ichiban"],["おいしい","oishii"],["。",""],["りょうりは","ryouriwa"],["おかあさんより","okaasanyori"],["じょうずだ","jouzuda"],["。",""]],"ko":[["아빠가","appaga"],["만든","mandeun"],["물고기","mulgogi"],["요리가","yoriga"],["제일","jeil"],["맛있어","matiteo"],[".",""],["아빠는","appaneun"],["엄마보다","eommaboda"],["요리를","yorireul"],["잘해","jalhae"],[".",""]]}');
