INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(235,3,105,'B','會。我會用手洗，也會用 machine。','Yes. I can wash by hand, and I can use a machine.','Oui. Je peux laver à la main, et je peux utiliser une machine.','できる。 手で あらって、 machineでも あらえる。','응. 손으로 빨 수도 있고, machine로도 빨 수 있어.','{"zh":[["會","huì"],["。",""],["我","wǒ"],["會","huì"],["用","yòng"],["手","shǒu"],["洗","xǐ"],["，",""],["也","yě"],["會","huì"],["用","yòng"],[" ",""],["m",""],["a",""],["c",""],["h",""],["i",""],["n",""],["e",""],["。",""]],"ja":[["できる","dekiru"],["。",""],["手で","tede"],["あらって","aratte"],["、",""],["machineでも","machinedemo"],["あらえる","araeru"],["。",""]],"ko":[["응","eung"],[".",""],["손으로","soneuro"],["빨","ppal"],["수도","sudo"],["있고","itgo"],[",",""],["machine로도","machinerodo"],["빨","ppal"],["수","su"],["있어","iteo"],[".",""]]}');
