INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(236,3,106,'A','我不太會洗衣服，都是媽媽做。','I am not good at washing clothes, mother does it all.','Je ne sais pas bien laver les vêtements, c''est maman qui fait tout.','わたしは 服を あらうのが へただ、 おかあさんが すべて する。','나는 옷을 잘 못 빨아, 모두 엄마가 해.','{"zh":[["我","wǒ"],["不","bù"],["太","tài"],["會","huì"],["洗","xǐ"],["衣","yī"],["服","fú"],["，",""],["都","dōu"],["是","shì"],["媽","mā"],["媽","mā"],["做","zuò"],["。",""]],"ja":[["わたしは","watashiwa"],["服を","fukuo"],["あらうのが","araunoga"],["へただ","hetada"],["、",""],["おかあさんが","okaasanga"],["すべて","subete"],["する","suru"],["。",""]],"ko":[["나는","naneun"],["옷을","oteul"],["잘","jal"],["못","mot"],["빨아","ppala"],[",",""],["모두","modu"],["엄마가","eommaga"],["해","hae"],[".",""]]}');
