INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(237,3,107,'B','你可以學。洗衣不難，水和 soap 就好。','You can learn. Washing clothes is not hard, water and soap are all you need.','Tu peux apprendre. Laver les vêtements n''est pas difficile, de l''eau et du savon sont tout ce qu''il faut.','ならえる。 服を あらうのは むずしくない、 水と soapが あれば いい。','배울 수 있어. 빨래는 어렵지 않아, 물과 soap이면 돼.','{"zh":[["你","nǐ"],["可","kě"],["以","yǐ"],["學","xué"],["。",""],["洗","xǐ"],["衣","yī"],["不","bù"],["難","nán"],["，",""],["水","shuǐ"],["和","hé"],[" ",""],["s",""],["o",""],["a",""],["p",""],[" ",""],["就","jiù"],["好","hǎo"],["。",""]],"ja":[["ならえる","naraeru"],["。",""],["服を","fukuo"],["あらうのは","araunowa"],["むずしくない","muzushikunai"],["、",""],["水と","mizuto"],["soapが","soapga"],["あれば","areba"],["いい","ii"],["。",""]],"ko":[["배울","baeul"],["수","su"],["있어","iteo"],[".",""],["빨래는","ppalraeneun"],["어렵지","eoryeopji"],["않아","ana"],[",",""],["물과","mulgwa"],["soap이면","soapimyeon"],["돼","dwae"],[".",""]]}');
