INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(250,3,120,'A','想寫 2 萬字。我不知道能不能寫完。','I want to write 20 thousand. I do not know if I can finish.','Je veux écrire 20 mille. Je ne sais pas si je peux finir.','2まんの ことばを かきたい。 おわりまで かげるか わからない。','2만 자를 쓰고 싶어. 끝낼 수 있는지 모르겠어.','{"zh":[["想","xiǎng"],["寫","xiě"],[" ",""],["2",""],[" ",""],["萬","wàn"],["字","zì"],["。",""],["我","wǒ"],["不","bù"],["知","zhī"],["道","dào"],["能","néng"],["不","bù"],["能","néng"],["寫","xiě"],["完","wán"],["。",""]],"ja":[["2まんの","2manno"],["ことばを","kotobao"],["かきたい","kakitai"],["。",""],["おわりまで","owarimade"],["かげるか","kageruka"],["わからない","wakaranai"],["。",""]],"ko":[["2만","2man"],["자를","jareul"],["쓰고","sseugo"],["싶어","sipeo"],[".",""],["끝낼","kkeutnael"],["수","su"],["있는지","itneunji"],["모르겠어","moreugeteo"],[".",""]]}');
