INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(251,3,121,'B','不要怕難。每天寫 1 page，一年就很多了。','Do not fear it is hard. Write 1 page every day, in one year it is a lot.','N''aie pas peur d''être difficile. Écris 1 page par jour, en un an ce sera beaucoup.','むずかしさに こわらないで。 まいにち 1ページ かけば、 1ねんで たくさん なる。','어려워도 무서워하지 마. 매일 1page 쓰면, 1년이면 많아져.','{"zh":[["不","bù"],["要","yào"],["怕","pà"],["難","nán"],["。",""],["每","měi"],["天","tiān"],["寫","xiě"],[" ",""],["1",""],[" ",""],["p",""],["a",""],["g",""],["e",""],["，",""],["一","yī"],["年","nián"],["就","jiù"],["很","hěn"],["多","duō"],["了","le"],["。",""]],"ja":[["むずかしさに","muzukashisani"],["こわらないで","kowaranaide"],["。",""],["まいにち","mainichi"],["1ページ","1peeji"],["かけば","kakeba"],["、",""],["1ねんで","1nende"],["たくさん","takusan"],["なる","naru"],["。",""]],"ko":[["어려워도","eoryeowodo"],["무서워하지","museowohaji"],["마","ma"],[".",""],["매일","maeil"],["1page","1page"],["쓰면","sseumyeon"],[",",""],["1년이면","1nyeonimyeon"],["많아져","manajyeo"],[".",""]]}');
