INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(253,3,123,'B','你看，那邊有一個老人。','Look, there is an old man there.','Regarde, il y a un vieil homme là-bas.','みて、 そこに 老人が いる。','봐, 저기에 할아버지가 있어.','{"zh":[["你","nǐ"],["看","kàn"],["，",""],["那","nà"],["邊","biān"],["有","yǒu"],["一","yī"],["個","gè"],["老","lǎo"],["人","rén"],["。",""]],"ja":[["みて","mite"],["、",""],["そこに","sokoni"],["老人が","roujinga"],["いる","iru"],["。",""]],"ko":[["봐","bwa"],[",",""],["저기에","jeogie"],["할아버지가","halabeojiga"],["있어","iteo"],[".",""]]}');
