INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(256,3,126,'A','真好。這麼大歲數還喜歡看書。','Very good. He is very old and he still likes reading books.','C''est bien vrai. Il est très vieux et il aime lire.','いいね。 かれは とても としを とっても ほんを よむのが すきだ。','참 좋아. 그렇게 나이 먹어도 책 읽기를 좋아해.','{"zh":[["真","zhēn"],["好","hǎo"],["。",""],["這","zhè"],["麼","me"],["大","dà"],["歲","suì"],["數","shù"],["還","hái"],["喜","xǐ"],["歡","huān"],["看","kàn"],["書","shū"],["。",""]],"ja":[["いいね","iine"],["。",""],["かれは","karewa"],["とても","totemo"],["としを","toshio"],["とっても","tottemo"],["ほんを","hono"],["よむのが","yomunoga"],["すきだ","sukida"],["。",""]],"ko":[["참","cham"],["좋아","jota"],[".",""],["그렇게","geureotge"],["나이","nai"],["먹어도","meokeodo"],["책","chaek"],["읽기를","ikgireul"],["좋아해","jotahae"],[".",""]]}');
