INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(257,3,127,'B','我想，人活到那麼大歲數，可以做很多想做的事。','I think, when a person lives that long, he can do many things he wants.','Je pense, quand on vit jusqu''à cet âge, on peut faire beaucoup de choses qu''on veut.','わたしは おもう、 ひとが そこまで いきると、 ほしいことが たくさん できる。','나는 생각해, 사람이 그 나이까지 살면, 하고 싶은 걸 많이 할 수 있다고.','{"zh":[["我","wǒ"],["想","xiǎng"],["，",""],["人","rén"],["活","huó"],["到","dào"],["那","nà"],["麼","me"],["大","dà"],["歲","suì"],["數","shù"],["，",""],["可","kě"],["以","yǐ"],["做","zuò"],["很","hěn"],["多","duō"],["想","xiǎng"],["做","zuò"],["的","de"],["事","shì"],["。",""]],"ja":[["わたしは","watashiwa"],["おもう","omou"],["、",""],["ひとが","hitoga"],["そこまで","sokomade"],["いきると","ikiruto"],["、",""],["ほしいことが","hoshiikotoga"],["たくさん","takusan"],["できる","dekiru"],["。",""]],"ko":[["나는","naneun"],["생각해","saenggakhae"],[",",""],["사람이","sarami"],["그","geu"],["나이까지","naikkaji"],["살면","salmyeon"],[",",""],["하고","hago"],["싶은","sipeun"],["걸","geol"],["많이","mani"],["할","hal"],["수","su"],["있다고","itdago"],[".",""]]}');
