INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(260,3,130,'A','好。50 歲的時候，我們一起去。','Ok. When I am 50, we go together.','Ok. Quand j''aurai 50 ans, nous irons ensemble.','いい。 50さいの とき、 いっしょに いこう。','그래. 50살 때 같이 가자.','{"zh":[["好","hǎo"],["。",""],["5",""],["0",""],[" ",""],["歲","suì"],["的","de"],["時","shí"],["候","hòu"],["，",""],["我","wǒ"],["們","men"],["一","yī"],["起","qǐ"],["去","qù"],["。",""]],"ja":[["いい","ii"],["。",""],["50さいの","50saino"],["とき","toki"],["、",""],["いっしょに","isshoni"],["いこう","ikou"],["。",""]],"ko":[["그래","geurae"],[".",""],["50살","50sal"],["때","ttae"],["같이","gati"],["가자","gaja"],[".",""]]}');
