INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(264,3,134,'B','是。星星比城裡多。','Yes. There are more stars than in the city.','Oui. Il y a plus d''étoiles qu''en ville.','そう。 まちより 星が たくさん ある。','응. 도시보다 별이 많아.','{"zh":[["是","shì"],["。",""],["星","xīng"],["星","xīng"],["比","bǐ"],["城","chéng"],["裡","lǐ"],["多","duō"],["。",""]],"ja":[["そう","sou"],["。",""],["まちより","machiyori"],["星が","hoshiga"],["たくさん","takusan"],["ある","aru"],["。",""]],"ko":[["응","eung"],[".",""],["도시보다","dosiboda"],["별이","byeoli"],["많아","mana"],[".",""]]}');
