INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(267,3,137,'A','以前媽媽說過一個名字。我記不得了。','Mother said a name before. I do not remember it.','Maman a dit un nom avant. Je ne m''en souviens pas.','まえに おかあさんが なまえを はなして いた。 わたしは おぼえて いない。','전에 엄마가 이름을 말했어. 나는 기억 못 해.','{"zh":[["以","yǐ"],["前","qián"],["媽","mā"],["媽","mā"],["說","shuō"],["過","guò"],["一","yī"],["個","gè"],["名","míng"],["字","zì"],["。",""],["我","wǒ"],["記","jì"],["不","bù"],["得","dé"],["了","le"],["。",""]],"ja":[["まえに","maeni"],["おかあさんが","okaasanga"],["なまえを","namaeo"],["はなして","hanashite"],["いた","ita"],["。",""],["わたしは","watashiwa"],["おぼえて","oboete"],["いない","inai"],["。",""]],"ko":[["전에","jeone"],["엄마가","eommaga"],["이름을","ireumeul"],["말했어","malhaeteo"],[".",""],["나는","naneun"],["기억","gieok"],["못","mot"],["해","hae"],[".",""]]}');
