INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(268,3,138,'B','沒事，以後我問了再和你說。','It is all right, later I will ask and then tell you.','Ce n''est rien, plus tard je demanderai et je te dirai.','だいじょうぶ、 あとで きいて おしえる。','괜찮아, 나중에 물어보고 알려 줄게.','{"zh":[["沒","méi"],["事","shì"],["，",""],["以","yǐ"],["後","hòu"],["我","wǒ"],["問","wèn"],["了","le"],["再","zài"],["和","hé"],["你","nǐ"],["說","shuō"],["。",""]],"ja":[["だいじょうぶ","daijoubu"],["、",""],["あとで","atode"],["きいて","kiite"],["おしえる","oshieru"],["。",""]],"ko":[["괜찮아","gwaenchana"],[",",""],["나중에","najunge"],["물어보고","muleobogo"],["알려","alryeo"],["줄게","julge"],[".",""]]}');
