INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(271,3,141,'A','我也是。不過明天還要上學。','Me too. But tomorrow I must go to school.','Moi aussi. Mais demain je dois aller à l''école.','わたしも そう。 けれど あしたは がっこうへ いかないと。','나도 그래. 하지만 내일도 학교에 가야 해.','{"zh":[["我","wǒ"],["也","yě"],["是","shì"],["。",""],["不","bù"],["過","guò"],["明","míng"],["天","tiān"],["還","hái"],["要","yào"],["上","shàng"],["學","xué"],["。",""]],"ja":[["わたしも","watashimo"],["そう","sou"],["。",""],["けれど","keredo"],["あしたは","ashitawa"],["がっこうへ","gakkoue"],["いかないと","ikanaito"],["。",""]],"ko":[["나도","nado"],["그래","geurae"],[".",""],["하지만","hajiman"],["내일도","naeildo"],["학교에","hakgyoe"],["가야","gaya"],["해","hae"],[".",""]]}');
