INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(302,4,28,'A','是。姐姐會做很多事，也會寫書。','Yes. My sister can do many things. She can also write books.','Oui. Ma sœur sait faire beaucoup de choses. Elle peut aussi écrire des livres.','うん。 おねえさんは たくさんの ことが できる。 ほんを かくことも できる。','응. 누나는 많은 일을 할 수 있어. 책도 쓸 수 있어.','{"zh":[["是","shì"],["。",""],["姐","jiě"],["姐","jiě"],["會","huì"],["做","zuò"],["很","hěn"],["多","duō"],["事","shì"],["，",""],["也","yě"],["會","huì"],["寫","xiě"],["書","shū"],["。",""]],"ja":[["うん","un"],["。",""],["おねえさんは","oneesanwa"],["たくさんの","takusanno"],["ことが","kotoga"],["できる","dekiru"],["。",""],["ほんを","hono"],["かくことも","kakukotomo"],["できる","dekiru"],["。",""]],"ko":[["응","eung"],[".",""],["누나는","nunaneun"],["많은","maneun"],["일을","ileul"],["할","hal"],["수","su"],["있어","iteo"],[".",""],["책도","chaekdo"],["쓸","sseul"],["수","su"],["있어","iteo"],[".",""]]}');
