INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(304,4,30,'A','我會寫書、會做飯、會做一個小 machine。','I can write books, cook, and make 1 small machine.','Je peux écrire des livres, cuisiner et faire une petite machine.','ほんを かく。 ごはんを つくる。 小さな machineを 1 つ つくる。','나는 책을 쓰고, 밥을 하고, 작은 machine 1 개를 만들어.','{"zh":[["我","wǒ"],["會","huì"],["寫","xiě"],["書","shū"],["、",""],["會","huì"],["做","zuò"],["飯","fàn"],["、",""],["會","huì"],["做","zuò"],["一","yī"],["個","gè"],["小","xiǎo"],[" ",""],["m",""],["a",""],["c",""],["h",""],["i",""],["n",""],["e",""],["。",""]],"ja":[["ほんを","hono"],["かく","kaku"],["。",""],["ごはんを","gohano"],["つくる","tsukuru"],["。",""],["小さな","chiisana"],["machineを","machineo"],["1","1"],["つ","tsu"],["つくる","tsukuru"],["。",""]],"ko":[["나는","naneun"],["책을","chaekeul"],["쓰고","sseugo"],[",",""],["밥을","bapeul"],["하고","hago"],[",",""],["작은","jakeun"],["machine","machine"],["1","1"],["개를","gaereul"],["만들어","mandeuleo"],[".",""]]}');
