INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(311,4,37,'B','媽媽的媽媽住在北方。明年我們去看媽媽的媽媽。','Mother''s mother stays far. Next year we will go to see mother''s mother.','La mère de ma mère reste très loin. L''année prochaine, nous irons voir la mère de ma mère.','おかあさんの おかあさんは きたに すんでいる。 ねんねん、 わたしたちは おかあさんの おかあさんに あいに いく。','엄마의 엄마는 멀리 있어요. 내일 해에 우리가 엄마의 엄마를 보러 가.','{"zh":[["媽","mā"],["媽","mā"],["的","de"],["媽","mā"],["媽","mā"],["住","zhù"],["在","zài"],["北","běi"],["方","fāng"],["。",""],["明","míng"],["年","nián"],["我","wǒ"],["們","men"],["去","qù"],["看","kàn"],["媽","mā"],["媽","mā"],["的","de"],["媽","mā"],["媽","mā"],["。",""]],"ja":[["おかあさんの","okaasanno"],["おかあさんは","okaasanwa"],["きたに","kitani"],["すんでいる","sundeiru"],["。",""],["ねんねん","nennen"],["、",""],["わたしたちは","watashitachiwa"],["おかあさんの","okaasanno"],["おかあさんに","okaasanni"],["あいに","aini"],["いく","iku"],["。",""]],"ko":[["엄마의","eommaui"],["엄마는","eommaneun"],["멀리","meolri"],["있어요","iteoyo"],[".",""],["내일","naeil"],["해에","haee"],["우리가","uriga"],["엄마의","eommaui"],["엄마를","eommareul"],["보러","boreo"],["가","ga"],[".",""]]}');
