INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(336,4,62,'B','因為海很大，看海，人就不會想不好的事。','The sea is very big. I look at the sea, I do not think bad things.','La mer est très grande. Je regarde la mer, je n''ai pas de mauvaises idées.','海が とても 大きいから。 海を みると、 わるい ことは かんがえない。','바다가 아주 크니까. 바다를 보면 나쁜 생각은 안 해.','{"zh":[["因","yīn"],["為","wèi"],["海","hǎi"],["很","hěn"],["大","dà"],["，",""],["看","kàn"],["海","hǎi"],["，",""],["人","rén"],["就","jiù"],["不","bù"],["會","huì"],["想","xiǎng"],["不","bù"],["好","hǎo"],["的","de"],["事","shì"],["。",""]],"ja":[["海が","umiga"],["とても","totemo"],["大きいから","ookiikara"],["。",""],["海を","umio"],["みると","miruto"],["、",""],["わるい","warui"],["ことは","kotowa"],["かんがえない","kangaenai"],["。",""]],"ko":[["바다가","badaga"],["아주","aju"],["크니까","keunikka"],[".",""],["바다를","badareul"],["보면","bomyeon"],["나쁜","nappeun"],["생각은","saenggakeun"],["안","an"],["해","hae"],[".",""]]}');
