INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(503,7,26,'B','我每個週都來。這裡的菜更新，錢也更少。','I come here every week. The food here is newer and the money is less.','Je viens ici chaque semaine. La nourriture ici est plus nouvelle et l''argent est plus petit.','わたしは まいしゅう ここへ くる。 ここの やさいは もっと あたらしく、 おかねも もっと すくない。','나는 매주 여기에 가. 여기 채소는 더 새롭고 돈도 더 적어.','{"zh":[["我","wǒ"],["每","měi"],["個","gè"],["週","zhōu"],["都","dōu"],["來","lái"],["。",""],["這","zhè"],["裡","lǐ"],["的","de"],["菜","cài"],["更","gèng"],["新","xīn"],["，",""],["錢","qián"],["也","yě"],["更","gèng"],["少","shǎo"],["。",""]],"ja":[["わたしは","watashiwa"],["まいしゅう","maishuu"],["ここへ","kokoe"],["くる","kuru"],["。",""],["ここの","kokono"],["やさいは","yasaiwa"],["もっと","motto"],["あたらしく","atarashiku"],["、",""],["おかねも","okanemo"],["もっと","motto"],["すくない","sukunai"],["。",""]],"ko":[["나는","naneun"],["매주","maeju"],["여기에","yeogie"],["가","ga"],[".",""],["여기","yeogi"],["채소는","chaesoneun"],["더","deo"],["새롭고","saeropgo"],["돈도","dondo"],["더","deo"],["적어","jeokeo"],[".",""]]}');
