INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(517,7,40,'A','是你媽媽生日？那我要買 cake。','Is it your mother''s birthday? Then I want to buy cake.','C''est l''anniversaire de ta mère ? Alors je veux acheter un gâteau.','おかあさんの たんじょうび？ じゃ ケーキを かう。','엄마 생일이야? 그럼 케이크를 살게.','{"zh":[["是","shì"],["你","nǐ"],["媽","mā"],["媽","mā"],["生","shēng"],["日","rì"],["？",""],["那","nà"],["我","wǒ"],["要","yào"],["買","mǎi"],[" ",""],["c",""],["a",""],["k",""],["e",""],["。",""]],"ja":[["おかあさんの","okaasanno"],["たんじょうび","tanjoubi"],["？",""],["じゃ","ja"],["ケーキを","keekio"],["かう","kau"],["。",""]],"ko":[["엄마","eomma"],["생일이야","saengiliya"],["?",""],["그럼","geureom"],["케이크를","keikeureul"],["살게","salge"],[".",""]]}');
