INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(556,8,12,'B','聽說下午有一點雨。你拿 umbrella。','I heard there is some rain in the afternoon. Take umbrella.','On dit qu''il y a un peu de pluie l''après-midi. Prends un parapluie.','ごごに あめが すこし ふるらしい。 umbrellaを もって いきな。','오후에 비가 조금 온다더라. umbrella를 가져가.','{"zh":[["聽","tīng"],["說","shuō"],["下","xià"],["午","wǔ"],["有","yǒu"],["一","yī"],["點","diǎn"],["雨","yǔ"],["。",""],["你","nǐ"],["拿","ná"],[" ",""],["u",""],["m",""],["b",""],["r",""],["e",""],["l",""],["l",""],["a",""],["。",""]],"ja":[["ごごに","gogoni"],["あめが","amega"],["すこし","sukoshi"],["ふるらしい","fururashii"],["。",""],["umbrellaを","umbrellao"],["もって","motte"],["いきな","ikina"],["。",""]],"ko":[["오후에","ohue"],["비가","biga"],["조금","jogeum"],["온다더라","ondadeora"],[".",""],["umbrella를","umbrellareul"],["가져가","gajyeoga"],[".",""]]}');
