INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(800,11,44,'B','我也是。這裡的甜點和媽媽做的一樣。','Me too. The food here is not different from mother''s.','Moi aussi. La chose que maman fait est ici aussi.','わたしも。 おかあさんが つくった ものも ここにある。','나도. 여긴 엄마가 만든 것과 같아.','{"zh":[["我","wǒ"],["也","yě"],["是","shì"],["。",""],["這","zhè"],["裡","lǐ"],["的","de"],["甜","tián"],["點","diǎn"],["和","hé"],["媽","mā"],["媽","mā"],["做","zuò"],["的","de"],["一","yī"],["樣","yàng"],["。",""]],"ja":[["わたしも","watashimo"],["。",""],["おかあさんが","okaasanga"],["つくった","tsukutta"],["ものも","monomo"],["ここにある","kokoniaru"],["。",""]],"ko":[["나도","nado"],[".",""],["여긴","yeogin"],["엄마가","eommaga"],["만든","mandeun"],["것과","geotgwa"],["같아","gata"],[".",""]]}');
