INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(849,12,34,'B','可以。每人可以拿 3 個，2 週裡要還。','Yes. Every person can take 3, and must give them back in 2 weeks.','Oui. Chaque personne peut prendre 3. Après 2 semaines, ils reviennent.','いいよ。 ひとりで 3 つ もって いい。 2 しゅうで かえして ね。','그래. 한 사람이 3개 가져가도 돼. 2주 후에 돌려줘야 해.','{"zh":[["可","kě"],["以","yǐ"],["。",""],["每","měi"],["人","rén"],["可","kě"],["以","yǐ"],["拿","ná"],[" ",""],["3",""],[" ",""],["個","gè"],["，",""],["2",""],[" ",""],["週","zhōu"],["裡","lǐ"],["要","yào"],["還","hái"],["。",""]],"ja":[["いいよ","iiyo"],["。",""],["ひとりで","hitoride"],["3","3"],["つ","tsu"],["もって","motte"],["いい","ii"],["。",""],["2","2"],["しゅうで","shuude"],["かえして","kaeshite"],["ね","ne"],["。",""]],"ko":[["그래","geurae"],[".",""],["한","han"],["사람이","sarami"],["3개","3gae"],["가져가도","gajyeogado"],["돼","dwae"],[".",""],["2주","2ju"],["후에","hue"],["돌려줘야","dolryeojwoya"],["해","hae"],[".",""]]}');
