INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(1022,14,24,'B','是。天空很藍，雲很少。','Yes. The sky is very blue. There are some clouds.','Oui. Le ciel est très bleu. Il y a quelques nuages.','うん。 そらは とても あおくて、 くもは すこし。','그래. 하늘은 아주 파래. 구름이 조금 있어.','{"zh":[["是","shì"],["。",""],["天","tiān"],["空","kōng"],["很","hěn"],["藍","lán"],["，",""],["雲","yún"],["很","hěn"],["少","shǎo"],["。",""]],"ja":[["うん","un"],["。",""],["そらは","sorawa"],["とても","totemo"],["あおくて","aokute"],["、",""],["くもは","kumowa"],["すこし","sukoshi"],["。",""]],"ko":[["그래","geurae"],[".",""],["하늘은","haneuleun"],["아주","aju"],["파래","parae"],[".",""],["구름이","gureumi"],["조금","jogeum"],["있어","iteo"],[".",""]]}');
