INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(1024,14,26,'B','最喜歡這樣的天氣。可以出去走。','I like this day the most. We can go out and walk.','J''aime ce temps le plus. On peut aller marcher.','わたしは この てんきが いちばん すきだ。 でて あるける。','나는 이런 날씨를 제일 좋아해. 나가서 걸을 수 있어.','{"zh":[["最","zuì"],["喜","xǐ"],["歡","huān"],["這","zhè"],["樣","yàng"],["的","de"],["天","tiān"],["氣","qì"],["。",""],["可","kě"],["以","yǐ"],["出","chū"],["去","qù"],["走","zǒu"],["。",""]],"ja":[["わたしは","watashiwa"],["この","kono"],["てんきが","tenkiga"],["いちばん","ichiban"],["すきだ","sukida"],["。",""],["でて","dete"],["あるける","arukeru"],["。",""]],"ko":[["나는","naneun"],["이런","ireon"],["날씨를","nalssireul"],["제일","jeil"],["좋아해","jotahae"],[".",""],["나가서","nagaseo"],["걸을","geoleul"],["수","su"],["있어","iteo"],[".",""]]}');
