INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(1111,15,50,'B','兩個都好。看書是為了工作，工作是為了生活。','Both are good. Reading books is for work, and work is for life.','Les deux sont bons. Lire des livres est pour le travail, le travail est pour nous.','どちらも いい。 ほんを よむのは しごとの ため。 しごとは 生きる ため。','둘 다 좋아. 책을 읽는 건 일을 위해서고, 일은 살기 위해서야.','{"zh":[["兩","liǎng"],["個","gè"],["都","dōu"],["好","hǎo"],["。",""],["看","kàn"],["書","shū"],["是","shì"],["為","wèi"],["了","le"],["工","gōng"],["作","zuò"],["，",""],["工","gōng"],["作","zuò"],["是","shì"],["為","wèi"],["了","le"],["生","shēng"],["活","huó"],["。",""]],"ja":[["どちらも","dochiramo"],["いい","ii"],["。",""],["ほんを","hono"],["よむのは","yomunowa"],["しごとの","shigotono"],["ため","tame"],["。",""],["しごとは","shigotowa"],["生きる","ikiru"],["ため","tame"],["。",""]],"ko":[["둘","dul"],["다","da"],["좋아","jota"],[".",""],["책을","chaekeul"],["읽는","ikneun"],["건","geon"],["일을","ileul"],["위해서고","wihaeseogo"],[",",""],["일은","ileun"],["살기","salgi"],["위해서야","wihaeseoya"],[".",""]]}');
