INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(1119,15,58,'B','因為錢不多。不過我可以學新的東西。','Because the money is not much. But I can learn new things.','Parce que l''argent n''est pas beaucoup. Mais je peux apprendre de nouvelles choses.','おかねが 少ないから。 ただし 新しい ものを まなべる。','돈이 많지 않아서. 하지만 새로운 걸 배울 수 있어.','{"zh":[["因","yīn"],["為","wèi"],["錢","qián"],["不","bù"],["多","duō"],["。",""],["不","bù"],["過","guò"],["我","wǒ"],["可","kě"],["以","yǐ"],["學","xué"],["新","xīn"],["的","de"],["東","dōng"],["西","xī"],["。",""]],"ja":[["おかねが","okanega"],["少ないから","sukunaikara"],["。",""],["ただし","tadashi"],["新しい","atarashii"],["ものを","monoo"],["まなべる","manaberu"],["。",""]],"ko":[["돈이","doni"],["많지","manji"],["않아서","anaseo"],[".",""],["하지만","hajiman"],["새로운","saeroun"],["걸","geol"],["배울","baeul"],["수","su"],["있어","iteo"],[".",""]]}');
INSERT INTO turns_fts(turn_id,lang,body) VALUES(1119,'zh','因 為 錢 不 多 不 過 我 可 以 學 新 的 東 西');
INSERT INTO turns_fts(turn_id,lang,body) VALUES(1119,'en','because the money is not much but i can learn new things');
INSERT INTO turns_fts(turn_id,lang,body) VALUES(1119,'fr','parce que l''argent n''est pas beaucoup mais je peux apprendre de nouvelles choses');
INSERT INTO turns_fts(turn_id,lang,body) VALUES(1119,'ja','お か ね が 少 な い か ら た だ し 新 し い も の を ま な べ る');
INSERT INTO turns_fts(turn_id,lang,body) VALUES(1119,'ko','돈이 많지 않아서 하지만 새로운 걸 배울 수 있어');
INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(1120,15,59,'A','這很重要。','This is very important.','C''est très important.','これは とても 重要だ。','이건 아주 중요해.','{"zh":[["這","zhè"],["很","hěn"],["重","zhòng"],["要","yào"],["。",""]],"ja":[["これは","korewa"],["とても","totemo"],["重要だ","juuyouda"],["。",""]],"ko":[["이건","igeon"],["아주","aju"],["중요해","jungyohae"],[".",""]]}');
