INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(1121,15,60,'B','是。下個月我要學新的東西。','Yes. Next month I will learn new things.','Oui. Le mois prochain, j''apprends de nouvelles choses.','うん。 つぎの つきに 新しい ものを まなぶぶ。','그래. 다음 달에 새로운 걸 배울 거야.','{"zh":[["是","shì"],["。",""],["下","xià"],["個","gè"],["月","yuè"],["我","wǒ"],["要","yào"],["學","xué"],["新","xīn"],["的","de"],["東","dōng"],["西","xī"],["。",""]],"ja":[["うん","un"],["。",""],["つぎの","tsugino"],["つきに","tsukini"],["新しい","atarashii"],["ものを","monoo"],["まなぶぶ","manabubu"],["。",""]],"ko":[["그래","geurae"],[".",""],["다음","daeum"],["달에","dale"],["새로운","saeroun"],["걸","geol"],["배울","baeul"],["거야","geoya"],[".",""]]}');
