INSERT OR REPLACE INTO turns(id,topic_id,idx,speaker,zh,en,fr,ja,ko,ruby) VALUES(1122,15,61,'A','那我們一起學。','Then we learn together.','Alors apprenons ensemble.','じゃ いっしょに まなびましょう。','그럼 같이 배워.','{"zh":[["那","nà"],["我","wǒ"],["們","men"],["一","yī"],["起","qǐ"],["學","xué"],["。",""]],"ja":[["じゃ","ja"],["いっしょに","isshoni"],["まなびましょう","manabimashou"],["。",""]],"ko":[["그럼","geureom"],["같이","gati"],["배워","baewo"],[".",""]]}');
